  json: {
    channel: 'webchat',
    external_id: body.session_id || body.visitor_id || null, // may be null until email/phone captured mid-conversation
    contact_name: body.name || null,
    contact_email: body.email || null,
    contact_phone: body.phone || null,
    message_text: body.message || '',
    thread_id: body.session_id,
    timestamp: new Date().toISOString()
  }
};

// Normalize inbound Gmail message to the common schema
const item = $input.item.json;
let fromHeader = item.from;
if (fromHeader && typeof fromHeader === 'object') {
  fromHeader = fromHeader.value?.[0]?.address || fromHeader.text || '';
}
fromHeader = fromHeader || '';
const emailMatch = fromHeader.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);

return {
  json: {
    channel: 'email',
    external_id: emailMatch ? emailMatch[0].toLowerCase() : null,
    contact_name: item.from?.value?.[0]?.name || null,
    contact_email: emailMatch ? emailMatch[0].toLowerCase() : null,
    contact_phone: null,
    message_text: item.text || '',
    thread_id: item.threadId,
    email_timestamp: item.date,
    timestamp: new Date().toISOString()
  }
};

// Normalize inbound Twilio SMS payload to the common schema
// Twilio sends application/x-www-form-urlencoded; n8n parses into body
const body = $input.item.json.body || $input.item.json;
const message = body.Body || body.chatInput || '';

function toE164(num) {
  if (!num) return null;
  const digits = num.replace(/\D/g, '').slice(-10);
  return digits.length === 10 ? '+92' + digits : null;
}
return {
  json: {
    channel: 'sms',
    external_id: toE164(body.From),
    contact_name: null,
    contact_email: null,
    contact_phone: toE164(body.From),
    message_text: message,
    thread_id: body.From || body.sessionId,
    timestamp: new Date().toISOString()
  }
};

// Normalize inbound WhatsApp Business Cloud payload to the common schema
const body = $input.item.json.body || $input.item.json;
function toE164(num) {
  if (!num) return null;
  const digits = num.replace(/\D/g, '').slice(-10);
  return digits.length === 10 ? '+92' + digits : null;
}
try {
  const entry = body.entry[0].changes[0].value;
  const msg = entry.messages[0];
  const contact = entry.contacts[0];
  return {
    json: {
      channel: 'whatsapp',
      phone_number_id: entry.metadata.phone_number_id,
      external_id: toE164(msg.from),
      contact_name: contact.profile.name || null,
      contact_email: null,
      contact_phone: toE164(msg.from),
      message_text: msg.text ? msg.text.body : '',
      thread_id: msg.from,
      timestamp: new Date().toISOString()
    }
  };
} catch (e) {
  // Malformed/unexpected payload shape (e.g. a status callback, not a message) — fail loudly, don't guess (Rule 5)
  return { json: { channel: 'whatsapp', error: 'unrecognized_payload_shape', raw: body } };
}

// Guard: drop malformed WhatsApp events before they hit identity resolution
if ($input.item.json.error) {
  throw new Error('Normalize - WhatsApp: ' + $input.item.json.error);
}
return $input.item;

