let full_input;
const candidates = [
  'If Volunteered Phone',
  'If Phone Present',
  'Guard - Drop Malformed WhatsApp',
  'Normalize - Email',
  'Normalize - Web Chat'
];
for (const name of candidates) {
  try {
    full_input = $(name).item.json;
    break;
  } catch (e) { /* not in this item's lineage, try next */ }
}

// Same extraction logic as "Extract Volunteered Email" — this path never ran it
//Extract Email Function:
function extractEmail(text) {
  if (typeof text !== 'string' || !text.trim()) {
    return null;
  }
  const normalized = text
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\u00A0/g, ' ');
  const regex =
    /(?<![A-Za-z0-9._%+-])[A-Za-z0-9._%+-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+(?=$|[^A-Za-z0-9])/;
  const match = normalized.match(regex);
  if (!match) {
    return null;
  }
  let email = match[0]
    .trim()
    .replace(/^[<("'`\[]+/, '')
    .replace(/[>)\]}"'`,;:!?]+$/, '')
    .toLowerCase();
  if (!email) {
    return null;
  }
  if (email.length > 254) {
    return null;
  }
  let [localPart, domain] = email.split('@');
  if (!localPart || !domain) {
    return null;
  }
  // Recover from a run of separator-like dots (e.g. an ellipsis before the real address)
  if (localPart.includes('..')) {
    const parts = localPart.split(/\.{2,}/);
    localPart = parts[parts.length - 1];
    if (!localPart) {
      return null;
    }
    email = `${localPart}@${domain}`;
  }
  if (localPart.startsWith('.') || localPart.endsWith('.')) {
    return null;
  }
  if (
    domain.startsWith('.') || domain.endsWith('.') ||
    domain.startsWith('-') || domain.endsWith('-') ||
    domain.includes('..')
  ) {
    return null;
  }
  const labels = domain.split('.');
  const tld = labels[labels.length - 1];
  if (!/^[A-Za-z]{2,24}$/.test(tld)) {
    return null;
  }
  return email;
}
let contactEmail = full_input.contact_email;
if (!contactEmail) {
  const text = full_input.message_text || '';

  contactEmail = extractEmail(text);
} else {
  contactEmail = contactEmail.toLowerCase();
}

return {
  json: {
    ...full_input,
    contact_email: contactEmail,
    hubspot_contact_id: $json.results[0].id,
