// Get the correct upstream normalized data depending on which route resolved
let full_input;
try {
  // Only succeeds if this item traveled the volunteered-phone-extraction route
  full_input = $('If Volunteered Phone').item.json;
} catch (e) {
  // Falls back here if the original transport-level phone existed and was searched directly
  full_input = $('If Phone Present').item.json;
}

const text = full_input.message_text || '';

const match = text.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);

if (!full_input.contact_email) {
  return {
    json: {
      ...full_input,
      contact_email: extractEmail(text) || null } };
} else {
  return { json: { ...full_input, contact_email: full_input.contact_email.toLowerCase() } };
