const input = $input.item.json;
let phone = input.contact_phone;
const message = input.message_text;

function toE164(num) {
  if (!num) return null;
  const digits = num.replace(/\D/g, '').slice(-10);
  return digits.length === 10 ? '+92' + digits : null;
}

//Extract Phone number from message boday if present
function extractPhoneNumber(messageBody) {
  if (!messageBody) return null;

  // 1. Matches common phone formats (7 to 15 digits, handles +, -, spaces, and brackets)
  const phoneRegex = /(?:\+?\d{1,3}[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4,6}/g;

  const match = messageBody.match(phoneRegex);

  if (match) {
    // 2. Take the first match and strip out spaces, dashes, and brackets
    // Keeps the leading '+' if present for international numbers
    const cleanPhone = match[0].replace(/[^\d+]/g, '');
    return cleanPhone;
  }

  return null; // Return null if no phone number is found
}
if (phone === null){
  phone = extractPhoneNumber(message);
}
phone = toE164(phone);

return {
  json: {

    ...input,
    contact_phone: phone
  }
};

