let contactId, resolutionMethod;
try {
  contactId = $('Set - Resolved via Phone').first().json.hubspot_contact_id;
  resolutionMethod = 'phone_match';
} catch (e) {
  try {
    contactId = $('Check Phone Conflict').first().json.hubspot_contact_id;
    resolutionMethod = 'email_match';
  } catch (e2) {
    try {
      contactId = $('Set - Resolved via Session').first().json.hubspot_contact_id;
      resolutionMethod = 'session_match';
    } catch (e3) {
      try {
        contactId = $('Create New Contact').first().json.id;
        resolutionMethod = 'new_contact';
      } catch (e4) {
        contactId = null;
        resolutionMethod = 'unknown';
      }
    }
  }
}
const anchor = $('If Phone Present').item.json;
return {
  json: {
    hubspot_contact_id: contactId,
    channel: anchor.channel,
    message_text: anchor.message_text,
    phone_number_id: anchor.phone_number_id || null,
    thread_id: anchor.thread_id,
    resolution_method: resolutionMethod,
    phone_conflict: $json.phone_conflict || false
  }
};

const authToken = $env.TWILIO_AUTH_TOKEN;
const crypto = require('crypto');
let valid = false;
try {
  const rawBody = Buffer.from($input.item.binary.data.data, 'base64').toString('utf-8');
  const expectedSignature = 'sha256=' + crypto.createHmac('sha256', authToken).update(rawBody).digest('hex');
  const receivedSignature = $json.headers['x-hub-signature-256'];
  valid = expectedSignature === receivedSignature;
} catch (e) {
  // No raw body present, or malformed request — treat as invalid rather than crashing.
  valid = false;
}

return { json: { ...$json, signature_valid: valid } };

const crypto = require('crypto');
const appSecret = $env.META_APP_SECRET;

let valid = false;
try {
  const rawBody = Buffer.from($input.item.binary.data.data, 'base64').toString('utf-8');
  const expectedSignature = 'sha256=' + crypto.createHmac('sha256', appSecret).update(rawBody).digest('hex');
  const receivedSignature = $json.headers['x-hub-signature-256'];
  valid = expectedSignature === receivedSignature;
} catch (e) {
  // No raw body present, or malformed request — treat as invalid rather than crashing.
  valid = false;
}

return { json: { ...$json, signature_valid: valid } };

let full_input;
try { full_input = $('Extract Volunteered Email').item.json; }
catch (e) { full_input = $('If Phone Present').item.json; }

return {
